-- Fakt kartochkalarining ruscha matni — 21-partiya: so'fiylar va muhaddislar.
-- Yusuf Hamadoniy, Ahmad Yassaviy, Najmiddin Kubro, Bahouddin Naqshband,
-- Hakim at-Termiziy, Imom at-Termiziy.

-- ===== Yusuf Hamadoniy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда родился Юсуф Хамадани?', fact_ru = 'Я родился в 1048 году. В источниках меня с почтением называют Ходжа Юсуф Хамадани. Всю свою жизнь я посвятил изучению наук и воспитанию учеников.' WHERE id = 2394;
UPDATE fact_cards SET topic_ru = 'Моё учительство в Бухаре', question_ru = 'Чем занимался Юсуф Хамадани в Бухаре?', fact_ru = 'Придя в Бухару, я обучал мюридов правилам суфизма. В ту пору Бухара была одним из средоточий науки и просвещения в Мавераннахре, и туда стекались искатели знания со всех концов Туркестана. Современники считали меня передовым учёным и суфием своего времени.' WHERE id = 2395;
UPDATE fact_cards SET topic_ru = 'Мои знаменитые ученики', question_ru = 'Какие ученики были у Юсуфа Хамадани?', fact_ru = 'В числе моих мюридов были такие суфии, как Ходжа Абдулхалик Гиждувани, Абдуллах Барки, Ходжа Хасан Андаки и Ходжа Ахмад Яссави. Абдулхалик Гиждувани был моим четвёртым халифом. Я воспитывал их как собственных детей.' WHERE id = 2396;
UPDATE fact_cards SET topic_ru = 'Моё наставничество Ахмаду Яссави', question_ru = 'Какое обучение прошёл Ахмад Яссави у Юсуфа Хамадани?', fact_ru = 'Ходжа Ахмад Яссави по указанию своего наставника Арслан-баба пришёл в Бухару, встретился со мной и стал моим мюридом. На моих беседах он учился вместе с Абдулхаликом Гиждувани, Абдуллахом Барки и Хасаном Андаки.' WHERE id = 2397;
UPDATE fact_cards SET topic_ru = 'Моё место в цепи ходжаган', question_ru = 'Каково место Юсуфа Хамадани в цепи ходжаган?', fact_ru = 'После меня мой ученик Ходжа Абдулхалик Гиждувани положил начало тарикату ходжаган, но первые семена этого учения посеял я.' WHERE id = 2398;
UPDATE fact_cards SET topic_ru = 'Я — пир Гиждувани', question_ru = 'Каким учеником был Абдулхалик Гиждувани у Юсуфа Хамадани?', fact_ru = 'Когда я пришёл в Бухару, двадцатидвухлетний Абдулхалик Гиждувани встретился со мной и стал моим учеником. Я был его пиром беседы и хирки, а он перенял у меня приёмы сулука в более широком объёме.' WHERE id = 2399;
UPDATE fact_cards SET topic_ru = 'Труд обо мне', question_ru = 'Какой труд написан о Юсуфе Хамадани?', fact_ru = 'Я скончался в 1140 году. После моей смерти мой ученик Абдулхалик Гиждувани оставил обо мне труд под названием «Макамати Юсуф Хамадани».' WHERE id = 2400;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Юсуф Хамадани?', fact_ru = 'В конце жизни я вернулся из Бухары в Хорасан. Я скончался в 1140 году. После меня моё учение продолжилось через моих учеников.' WHERE id = 2401;

-- ===== Ahmad Yassaviy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Где родился Ахмад Яссави и кем были его родители?', fact_ru = 'Я появился на свет в городе Сайрам близ Яссы. Мой отец — шейх Ибрахим, а мать — Айша-хатун, дочь Мусы-шейха.' WHERE id = 1952;
UPDATE fact_cards SET topic_ru = 'Моё детство и моя сестра', question_ru = 'Кто занимался воспитанием Ахмада Яссави?', fact_ru = 'Мать умерла вскоре после моего рождения, а в семь лет я лишился и отца. Моим воспитанием занималась сестра Гавхар Шахноз, и вместе с ней я переселился в город Ясса.' WHERE id = 1953;
UPDATE fact_cards SET topic_ru = 'Мои наставники', question_ru = 'Кто были наставниками Ахмада Яссави?', fact_ru = 'В семь лет в Яссе я встретился с первым моим наставником Арслан-бабом и учился у него. Затем я отправился в Бухару — средоточие науки — и стал мюридом шейха Юсуфа Хамадани.' WHERE id = 1954;
UPDATE fact_cards SET topic_ru = 'Мой тарикат', question_ru = 'Чем прославился Ахмад Яссави, вернувшись в Яссу?', fact_ru = 'Вернувшись из Бухары в Яссу, я прославился как муршид, положивший начало новому тарикату. Моей целью было ещё шире привлечь тюркские народы к исламу.' WHERE id = 1955;
UPDATE fact_cards SET topic_ru = 'Мой «Диван мудрости»', question_ru = 'Как появился труд «Диван мудрости»?', fact_ru = 'В своих стихах я воспевал божественную любовь и влюблённость, просветление и блаженство познания. Мои хикматы собрали мои мюриды и последователи и составили из них диван «Диван мудрости».' WHERE id = 1956;
UPDATE fact_cards SET topic_ru = 'Моя поэзия и моя цель', question_ru = 'С какой целью Ахмад Яссави обращался к поэзии?', fact_ru = 'Я обращался к поэзии, чтобы ещё шире привлечь тюркские народы к исламу и глубоко внедрить идеи суфизма в души людей. Свои хикматы я говорил языком, понятным простому народу.' WHERE id = 1957;
UPDATE fact_cards SET topic_ru = 'Моя подземная келья', question_ru = 'В каком возрасте Ахмад Яссави затворился в подземной келье?', fact_ru = 'Достигнув шестидесяти трёх лет, я затворился в подземной келье и посвятил свою жизнь подвижничеству и молитве. Об этом в своём хикмате я сказал: «В шестьдесят три под землю сошёл я».' WHERE id = 1958;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Ахмад Яссави и где он погребён?', fact_ru = 'Я скончался в 1166 году. Моё тело погребено в городе, где я вырос, — в древней Яссе.' WHERE id = 1959;

-- ===== Najmiddin Kubro =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Где родился Наджмиддин Кубра?', fact_ru = 'Я родился в 1145 году в нынешнем селении Саят близ Хивы. Моя родина — древняя земля Хорезма.' WHERE id = 1897;
UPDATE fact_cards SET topic_ru = 'Моё имя и моё прозвище', question_ru = 'Каким прозвищем прославился Наджмиддин Кубра?', fact_ru = 'Моё полное имя — Ахмад ибн Умар Абульджаннаб Наджмиддин аль-Кубра аль-Хиваки аль-Хорезми. В народе я прославился под именем «Шейхи валийтарош», то есть «шейх, взращивающий святых».' WHERE id = 1898;
UPDATE fact_cards SET topic_ru = 'Тарикат кубравия', question_ru = 'Какому тарикату положил начало Наджмиддин Кубра?', fact_ru = 'Я положил начало знаменитому в суфизме тарикату кубравия. Люди нашего тариката проповедовали тайный зикр, а наше учение распространилось главным образом в Средней Азии и отчасти в Иране.' WHERE id = 1899;
UPDATE fact_cards SET topic_ru = 'Мои труды', question_ru = 'Какие труды Наджмиддина Кубры знамениты?', fact_ru = 'Науке известно около десяти моих трудов. Среди них знамениты книги «Аль-усуль аль-ашара» («Десять правил»), «Фавойих уль-джамол ва фавотих уль-джалол», «Тафсир» и «Шарх ус-сунна валь-масолик».' WHERE id = 1900;
UPDATE fact_cards SET topic_ru = 'Языки, на которых я писал', question_ru = 'На каком языке главным образом писал свои труды Наджмиддин Кубра?', fact_ru = 'Свои труды я писал главным образом на арабском языке. Только труд «Фи одоб ус-соликин» («О правилах поведения идущих по пути»), созданный как пособие для начинающих суфиев, и свои рубаи я написал на персидском.' WHERE id = 1901;
UPDATE fact_cards SET topic_ru = 'Мои рубаи', question_ru = 'Какие темы воспевал Наджмиддин Кубра в своих рубаи?', fact_ru = 'Слагал я и рубаи. В них изображены поиск Истины, воспевание любви к Аллаху, призыв на путь Истины, а также думы и переживания, тяготы и муки идущего по пути на разных его ступенях.' WHERE id = 1902;
UPDATE fact_cards SET topic_ru = 'Моя любовь к мюридам', question_ru = 'Как Наджмиддин Кубра спас своих мюридов, когда пришли монголы?', fact_ru = 'Когда монгольские полчища вторглись на хорезмскую землю, я не пожелал, чтобы мои мюриды из других краёв погибли на чужой земле, и отослал их на родину.' WHERE id = 1903;
UPDATE fact_cards SET topic_ru = 'Оборона Хорезма', question_ru = 'Что сказал Наджмиддин Кубра своим ученикам, выступая на оборону города?', fact_ru = 'Сам же я выступил на оборону города. На предложения учеников уйти вместе я ответил: «Я приму здесь мученическую смерть. Мне не дозволено покидать Хорезм!» — и, взяв в руку саблю и наполнив пазуху камнями, вышел навстречу врагу.' WHERE id = 1904;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и как погиб Наджмиддин Кубра?', fact_ru = 'Я пал в 1221 году, приняв мученическую смерть при обороне родины. Враги пустили в меня стрелы из лука, одна из них вонзилась мне в грудь; но и тогда я крепко сжимал вырванное из рук врага знамя.' WHERE id = 1905;

-- ===== Bahouddin Naqshband =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Бахауддин Накшбанд?', fact_ru = 'Я родился в 1318 году в селении Касри Хиндуян (Касри Орифон) под Бухарой. Моё полное имя — Сайид Мухаммад Бахауддин ибн Сайид Джалалиддин.' WHERE id = 1906;
UPDATE fact_cards SET topic_ru = 'Моя юность и науки', question_ru = 'Какими науками основательно овладел Бахауддин Накшбанд в юности?', fact_ru = 'С юных лет я вступил на путь суфизма и изучал его тайны. Я основательно овладел Священным Кораном, толкованием и хадисами.' WHERE id = 1907;
UPDATE fact_cards SET topic_ru = 'Моё прозвище «Накшбанд»', question_ru = 'Почему Бахауддин получил прозвище «Накшбанд»?', fact_ru = 'Я занимался земледелием, а позже наносил разные узоры на шёлковые ткани, на железные и медные изделия. Оттого моим прозвищем и стало «Накшбанд» — «наносящий узор».' WHERE id = 1908;
UPDATE fact_cards SET topic_ru = 'Мой наставник', question_ru = 'Кого Бахауддин Накшбанд считал своим пиром и учителем?', fact_ru = 'Своим пиром и учителем я считал Абдулхалика Гиждувани и развивал его учение.' WHERE id = 1909;
UPDATE fact_cards SET topic_ru = 'Мои труды', question_ru = 'Сколько трудов по суфизму написал Бахауддин Накшбанд и какие из них знамениты?', fact_ru = 'Я написал 13 трудов по теории и практике суфизма. Среди них особое значение имеют такие труды, как «Хаётнаме», «Далили ошикон», «Одоб ас-соликин».' WHERE id = 1910;
UPDATE fact_cards SET topic_ru = 'Тарикат накшбандия', question_ru = 'Какому тарикату положил начало Бахауддин Накшбанд и где он его проповедовал?', fact_ru = 'Я положил начало тарикату «накшбандия». Я широко проповедовал суфизм в Аравии, Иране и во многих городах Центральной Азии.' WHERE id = 1911;
UPDATE fact_cards SET topic_ru = 'Мой девиз', question_ru = 'Каков главный девиз накшбандии и что он означает?', fact_ru = 'Суть моего учения выражена в девизе «Даст ба кору, дил ба ёр!» — то есть «Рука в труде, а сердце с Господом».' WHERE id = 1912;
UPDATE fact_cards SET topic_ru = 'Моё имя «Балогардон»', question_ru = 'Какое имя дал народ Бахауддину Накшбанду и почему?', fact_ru = 'Моё имя «Бахауддин» означает «гордость веры». А за то, что я был человеком, наделённым благодатью, мне дали имя «Балогардон» — «отводящий беду».' WHERE id = 1913;
UPDATE fact_cards SET topic_ru = 'Мои последователи', question_ru = 'Какие великие люди избрали путь накшбандии?', fact_ru = 'Я скончался в 1389 году и потому не застал последующих времён. После меня путь накшбандии избрали Амир Темур, Алишер Навои, Абдурахман Джами, Махтумкули и другие великие люди.' WHERE id = 1914;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Бахауддин Накшбанд?', fact_ru = 'Я скончался в 1389 году в своём селении. В 1993 году в Узбекистане широко отмечалось 675-летие со дня моего рождения.' WHERE id = 1915;

-- ===== Hakim at-Termiziy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Хаким ат-Термизи?', fact_ru = 'Я появился на свет в древнем городе Термез. Год моего рождения точно не известен — я родился примерно между 750 и 760 годами и прожил долгую жизнь, 116 или 120 лет. Моё полное имя — Абу Абдуллах Мухаммад ибн Али ибн аль-Хасан ибн Башир аль-Хаким ат-Термизи.' WHERE id = 2186;
UPDATE fact_cards SET topic_ru = 'Моё детство и мои наставники', question_ru = 'У кого учился Хаким ат-Термизи?', fact_ru = 'Мой отец Али ибн аль-Хасан ат-Термизи был зрелым учёным в науке хадисов, и первые уроки я получил у него. В восемь лет я лишился отца и затем продолжил учение у известных термезских учёных.' WHERE id = 2187;
UPDATE fact_cards SET topic_ru = 'Моё паломничество', question_ru = 'В какие города странствовал Хаким ат-Термизи?', fact_ru = 'Когда мне шёл двадцать восьмой год, я через Ирак отправился в священную Мекку и совершил хадж. Возвращаясь на родину, я почувствовал, что в душе моей родилось сильное стремление выучить Священный Коран наизусть. За свою жизнь я побывал и в городах Нишапур и Балх.' WHERE id = 2188;
UPDATE fact_cards SET topic_ru = 'Мои труды', question_ru = 'Сколько трудов написал Хаким ат-Термизи?', fact_ru = 'За свою жизнь я написал около четырёхсот трудов. Среди моих книг есть такие, как «Навадир уль-усуль», «Ильм уль-авлия», «Адаб ун-нафс» и «Маназиль уль-ибад».' WHERE id = 2189;
UPDATE fact_cards SET topic_ru = 'Мой труд «Хатм уль-авлия»', question_ru = 'О чём труд «Хатм уль-авлия»?', fact_ru = 'Моя самая знаменитая книга — «Хатм уль-авлия». Этот мой труд состоит из предисловия и 29 глав; в нём я положил начало учению о святости.' WHERE id = 2190;
UPDATE fact_cards SET topic_ru = 'Мои ученики и хакимия', question_ru = 'Какое течение суфизма связано с Хакимом ат-Термизи?', fact_ru = 'Я воспитал множество учеников; среди них Абу Мухаммад Яхья ибн Мансур аль-Кази, Абу Али аль-Хасан ибн Али аль-Джурджани и Абу Бакр Мухаммад ибн Умар аль-Варрак. Моё учение продолжилось через моих учеников и последователей.' WHERE id = 2191;
UPDATE fact_cards SET topic_ru = 'Годы моих испытаний', question_ru = 'Почему Хаким ат-Термизи был изгнан из Термеза?', fact_ru = 'После того как вышли в свет некоторые мои труды, часть людей выступила против меня, и я был изгнан из родного Термеза и несколько лет жил в Балхе. Правитель Балха взял с меня обещание не говорить о любви к Аллаху и держаться в уединении от людей.' WHERE id = 2192;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Хаким ат-Термизи и где его мавзолей?', fact_ru = 'Я скончался в 255 году хиджры — 869 году. Эта же дата высечена на моём надгробии. Мой мавзолей расположен близ города Термез, на берегу Амударьи.' WHERE id = 2193;

-- ===== Imom at-Termiziy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Имам ат-Термизи?', fact_ru = 'Я родился в 209 году хиджры — 824 году — в селении Буг близ Термеза, в семье среднего достатка. Моё полное имя — Мухаммад ибн Иса ибн Саура ибн Муса ибн аз-Заххак Абу Иса ас-Сулами аз-Зарир аль-Буги ат-Термизи.' WHERE id = 1867;
UPDATE fact_cards SET topic_ru = 'Мои прозвища', question_ru = 'Почему ат-Термизи получил прозвище аз-Зарир?', fact_ru = 'Я скончался в 892 году в селении Буг — и оттого, что умер именно в этом селении, меня называют также прозвищем аль-Буги. От многих слёз к концу жизни я потерял зрение, потому и получил прозвище аз-Зарир, то есть «незрячий».' WHERE id = 1868;
UPDATE fact_cards SET topic_ru = 'Мои странствия за знанием', question_ru = 'С какого возраста ат-Термизи отправился странствовать в поисках знания?', fact_ru = 'От жажды знания я с 850 года, то есть с двадцати шести лет, странствовал по дальним краям. В Хиджазе — в Мекке и Медине, в Ираке, во многих городах Хорасана — я общался со множеством мухаддисов и учёных и учился у них.' WHERE id = 1869;
UPDATE fact_cards SET topic_ru = 'Мои наставники и ученики', question_ru = 'Кто были наставниками ат-Термизи?', fact_ru = 'Среди моих наставников такие знаменитые мухаддисы, как Имам аль-Бухари, Имам Муслим ибн аль-Хаджжадж, Абу Дауд, Кутайба ибн Саид. И сам я был наставником множеству учеников — среди них Макхуль ибн аль-Фазль, Хаммад ибн Шакир, Хайсам ибн Кулайб аш-Шаши.' WHERE id = 1870;
UPDATE fact_cards SET topic_ru = 'Моя крепкая память', question_ru = 'Какое предание сохранилось о памяти ат-Термизи?', fact_ru = 'Когда я направлялся в Мекку, один учёный пересказал мне около семидесяти различных хадисов. Увидев, что на моей бумаге нет никаких записей, он разгневался, — и тогда я одно за другим повторил наизусть все услышанные хадисы.' WHERE id = 1871;
UPDATE fact_cards SET topic_ru = 'Как я отбирал хадисы', question_ru = 'На какие степени разделял хадисы ат-Термизи?', fact_ru = 'Я последовательно устанавливал происхождение и иснад каждого услышанного хадиса и заносил его на особые листы лишь тогда, когда обретал полную уверенность в его достоверности. Так я разделил хадисы на такие разряды, как сахих, хасан, даиф, гариб.' WHERE id = 1872;
UPDATE fact_cards SET topic_ru = '«Аль-Джами ас-сахих»', question_ru = 'Когда ат-Термизи окончил труд «Аль-Джами ас-сахих»?', fact_ru = 'Свой главный труд «Аль-Джами ас-сахих» я окончил в 270 году хиджры — 884 году, почти в шестьдесят лет. Когда я показал его учёным Хиджаза, Ирака и Хорасана, они единогласно его одобрили.' WHERE id = 1873;
UPDATE fact_cards SET topic_ru = 'Мои труды', question_ru = 'Сколько трудов создал ат-Термизи?', fact_ru = 'За свою творческую жизнь я создал более десяти трудов. Среди них такие книги, как «Аль-Джами ас-сахих», «Аш-шамаиль ан-набавия», «Китаб ат-тарих», «Китаб уз-зухд», «Китаб аль-асма валь-куна», «Аль-илаль филь-хадис».' WHERE id = 1874;
UPDATE fact_cards SET topic_ru = 'Труд «Аш-шамаиль»', question_ru = 'Сколько хадисов собрано в труде «Аш-шамаиль ан-набавия»?', fact_ru = 'Один из крупнейших моих трудов «Аш-шамаиль ан-набавия» собрал четыреста восемь священных хадисов об облике и нраве Пророка, мир ему, о его дивных достоинствах и обычаях. Мой труд разделён на пятьдесят шесть глав.' WHERE id = 1875;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Имам ат-Термизи?', fact_ru = 'После возвращения из странствий на родину я создал многие свои труды, в том числе знаменитый «Аль-Джами». Я скончался в 892 году в селении Буг близ Термеза и там же погребён.' WHERE id = 1876;
